// SPDX-License-Identifier: ISC
//! Go 1.26.5's `encoding/json` and `strconv` texts that the Go-JSON
//! layer reproduces, generated by running the Go calls named on each
//! table under the go1.26.5 toolchain (the parity reference binary's
//! version, whose `encoding/json` is the v1 package): the scanner's
//! message for input cut off inside a token, the escapes of the string
//! encoder and of `strconv.Quote`, the shortest float digits at an
//! exact tie, the strconv parsers' sign and hexadecimal-float handling,
//! and the struct decoder's case-folded key match.

use dcroxide_dcrjson::gojson::{
    self, append_json_string, format_float_f, format_float_g, format_float_g32, format_float_json,
    format_float_json32, go_fold_eq, go_parse_float, go_parse_int, go_quote, validate,
};
use dcroxide_dcrjson::{GoType, GoValue, StructField};

/// `json.Unmarshal(in, &v)` into an `any`: its error text, `None` when
/// the document is valid.  At end of input Go's `checkValid` steps a
/// synthetic space into the scanner, so input cut off inside a number,
/// a literal, a string escape or a `\u` escape reports that state's
/// "invalid character ' '" message; only a cut between tokens or inside
/// a string body is "unexpected end of JSON input".
const TRUNCATED: &[(&str, Option<&str>)] = &[
    ("-", Some("invalid character ' ' in numeric literal")),
    (
        "1.",
        Some("invalid character ' ' after decimal point in numeric literal"),
    ),
    (
        "1e",
        Some("invalid character ' ' in exponent of numeric literal"),
    ),
    (
        "1E",
        Some("invalid character ' ' in exponent of numeric literal"),
    ),
    (
        "1e+",
        Some("invalid character ' ' in exponent of numeric literal"),
    ),
    (
        "1e-",
        Some("invalid character ' ' in exponent of numeric literal"),
    ),
    (
        "-0.",
        Some("invalid character ' ' after decimal point in numeric literal"),
    ),
    (
        "0e",
        Some("invalid character ' ' in exponent of numeric literal"),
    ),
    (
        "-1.5e",
        Some("invalid character ' ' in exponent of numeric literal"),
    ),
    (
        "t",
        Some("invalid character ' ' in literal true (expecting 'r')"),
    ),
    (
        "tr",
        Some("invalid character ' ' in literal true (expecting 'u')"),
    ),
    (
        "tru",
        Some("invalid character ' ' in literal true (expecting 'e')"),
    ),
    (
        "f",
        Some("invalid character ' ' in literal false (expecting 'a')"),
    ),
    (
        "fa",
        Some("invalid character ' ' in literal false (expecting 'l')"),
    ),
    (
        "fal",
        Some("invalid character ' ' in literal false (expecting 's')"),
    ),
    (
        "fals",
        Some("invalid character ' ' in literal false (expecting 'e')"),
    ),
    (
        "n",
        Some("invalid character ' ' in literal null (expecting 'u')"),
    ),
    (
        "nu",
        Some("invalid character ' ' in literal null (expecting 'l')"),
    ),
    (
        "nul",
        Some("invalid character ' ' in literal null (expecting 'l')"),
    ),
    ("\"a\\", Some("invalid character ' ' in string escape code")),
    (
        "\"\\u",
        Some("invalid character ' ' in \\u hexadecimal character escape"),
    ),
    (
        "\"\\u1",
        Some("invalid character ' ' in \\u hexadecimal character escape"),
    ),
    (
        "\"\\u12",
        Some("invalid character ' ' in \\u hexadecimal character escape"),
    ),
    (
        "\"\\u123",
        Some("invalid character ' ' in \\u hexadecimal character escape"),
    ),
    ("\"abc", Some("unexpected end of JSON input")),
    ("\"", Some("unexpected end of JSON input")),
    ("[", Some("unexpected end of JSON input")),
    ("{", Some("unexpected end of JSON input")),
    ("{\"a\"", Some("unexpected end of JSON input")),
    ("{\"a\":", Some("unexpected end of JSON input")),
    ("{\"a\":1", Some("unexpected end of JSON input")),
    ("[1", Some("unexpected end of JSON input")),
    ("[1,", Some("unexpected end of JSON input")),
    ("[-", Some("invalid character ' ' in numeric literal")),
    (
        "[1.",
        Some("invalid character ' ' after decimal point in numeric literal"),
    ),
    (
        "[tru",
        Some("invalid character ' ' in literal true (expecting 'e')"),
    ),
    (
        "{\"a\":tru",
        Some("invalid character ' ' in literal true (expecting 'e')"),
    ),
    (
        "{\"a\":\"\\",
        Some("invalid character ' ' in string escape code"),
    ),
    (
        "[\"\\u00",
        Some("invalid character ' ' in \\u hexadecimal character escape"),
    ),
    ("", Some("unexpected end of JSON input")),
    (" ", Some("unexpected end of JSON input")),
    ("1 ", None),
    ("[1e5", Some("unexpected end of JSON input")),
    ("-0", None),
    ("0.5", None),
    ("12e+3", None),
    (
        "{\"jsonrpc\":\"1.0\",\"id\":1,\"method\":\"getblockcount\",\"params\":[tru",
        Some("invalid character ' ' in literal true (expecting 'e')"),
    ),
    (
        "{\"jsonrpc\":\"1.0\",\"id\":1,\"method\":\"getblockcount\",\"params\":[-",
        Some("invalid character ' ' in numeric literal"),
    ),
    (
        "{\"jsonrpc\":\"1.0\",\"id\":1,\"method\":\"getblockcount\",\"params\":[1.",
        Some("invalid character ' ' after decimal point in numeric literal"),
    ),
    (
        "{\"jsonrpc\":\"1.0\",\"id\":1,\"method\":\"getblockcount\",\"params\":[\"\\",
        Some("invalid character ' ' in string escape code"),
    ),
];

#[test]
fn input_cut_off_inside_a_token_reports_the_space_eof_steps_in() {
    for (input, want) in TRUNCATED {
        let got = validate(input).err().map(|e| e.go_message());
        assert_eq!(got.as_deref(), *want, "input {input:?}");
    }
}

/// `json.Marshal("a" + string(r) + "b")`: `appendString` names `\b`,
/// `\f`, `\n`, `\r` and `\t`, spells the other controls `\u00XX`,
/// HTML-escapes `<`, `>` and `&`, and escapes U+2028/9; DEL and the
/// other runes pass through.
const STRING_ESCAPES: &[(char, &str)] = &[
    ('\u{0}', "\"a\\u0000b\""),
    ('\u{1}', "\"a\\u0001b\""),
    ('\u{2}', "\"a\\u0002b\""),
    ('\u{3}', "\"a\\u0003b\""),
    ('\u{4}', "\"a\\u0004b\""),
    ('\u{5}', "\"a\\u0005b\""),
    ('\u{6}', "\"a\\u0006b\""),
    ('\u{7}', "\"a\\u0007b\""),
    ('\u{8}', "\"a\\bb\""),
    ('\u{9}', "\"a\\tb\""),
    ('\u{a}', "\"a\\nb\""),
    ('\u{b}', "\"a\\u000bb\""),
    ('\u{c}', "\"a\\fb\""),
    ('\u{d}', "\"a\\rb\""),
    ('\u{e}', "\"a\\u000eb\""),
    ('\u{f}', "\"a\\u000fb\""),
    ('\u{10}', "\"a\\u0010b\""),
    ('\u{11}', "\"a\\u0011b\""),
    ('\u{12}', "\"a\\u0012b\""),
    ('\u{13}', "\"a\\u0013b\""),
    ('\u{14}', "\"a\\u0014b\""),
    ('\u{15}', "\"a\\u0015b\""),
    ('\u{16}', "\"a\\u0016b\""),
    ('\u{17}', "\"a\\u0017b\""),
    ('\u{18}', "\"a\\u0018b\""),
    ('\u{19}', "\"a\\u0019b\""),
    ('\u{1a}', "\"a\\u001ab\""),
    ('\u{1b}', "\"a\\u001bb\""),
    ('\u{1c}', "\"a\\u001cb\""),
    ('\u{1d}', "\"a\\u001db\""),
    ('\u{1e}', "\"a\\u001eb\""),
    ('\u{1f}', "\"a\\u001fb\""),
    ('\u{7f}', "\"a\u{7f}b\""),
    ('\u{3c}', "\"a\\u003cb\""),
    ('\u{3e}', "\"a\\u003eb\""),
    ('\u{26}', "\"a\\u0026b\""),
    ('\u{2028}', "\"a\\u2028b\""),
    ('\u{2029}', "\"a\\u2029b\""),
    ('\u{22}', "\"a\\\"b\""),
    ('\u{5c}', "\"a\\\\b\""),
    ('\u{a0}', "\"a\u{a0}b\""),
    ('\u{ad}', "\"a\u{ad}b\""),
    ('\u{fffd}', "\"a\u{fffd}b\""),
];

#[test]
fn string_encoder_matches_go_append_string() {
    for (c, want) in STRING_ESCAPES {
        let mut got = String::new();
        append_json_string(&mut got, &format!("a{c}b"));
        assert_eq!(&got, want, "rune {:#x}", u32::from(*c));
    }
}

/// `strconv.Quote(s)`, the `%q` verb dcrd's `rpcDecodeHexError` uses:
/// the named C escapes, `\x` for the other ASCII controls and DEL, and
/// `\u`/`\U` for every rune `strconv.IsPrint` rejects -- format and
/// separator characters, private-use, noncharacter and unassigned runes
/// alike.
const QUOTES: &[(&str, &str)] = &[
    ("\u{7}\u{8}\u{c}\u{b}\u{7f}", "\"\\a\\b\\f\\v\\x7f\""),
    (
        "\u{a0}\u{ad}\u{200b}\u{e000}",
        "\"\\u00a0\\u00ad\\u200b\\ue000\"",
    ),
    ("abc", "\"abc\""),
    ("a\"b\\c", "\"a\\\"b\\\\c\""),
    ("\u{0}\u{1}\u{1f}", "\"\\x00\\x01\\x1f\""),
    ("\u{378}", "\"\\u0378\""),
    ("\u{2028}\u{2029}", "\"\\u2028\\u2029\""),
    ("\u{feff}", "\"\\ufeff\""),
    ("\u{fffd}", "\"\u{fffd}\""),
    ("\u{10000}", "\"\u{10000}\""),
    ("\u{1f600}", "\"\u{1f600}\""),
    ("\u{e0001}", "\"\\U000e0001\""),
    ("\u{f0000}", "\"\\U000f0000\""),
    ("\u{10ffff}", "\"\\U0010ffff\""),
    ("\u{600}", "\"\\u0600\""),
    ("\u{61c}", "\"\\u061c\""),
    ("\u{180e}", "\"\\u180e\""),
    ("\u{3000}", "\"\\u3000\""),
    ("\u{1d173}", "\"\\U0001d173\""),
    ("\u{80}\u{9f}", "\"\\u0080\\u009f\""),
    ("éÿ¡", "\"éÿ¡\""),
    ("\u{300}", "\"\u{300}\""),
    ("\u{2066}", "\"\\u2066\""),
    ("\u{1bca0}", "\"\\U0001bca0\""),
    ("\u{e0100}", "\"\u{e0100}\""),
    ("\u{2a6df}", "\"\u{2a6df}\""),
    ("\u{2a6e0}", "\"\\U0002a6e0\""),
    ("\u{3134a}", "\"\u{3134a}\""),
    ("\u{3134b}", "\"\\U0003134b\""),
    ("\u{31ef}", "\"\\u31ef\""),
    ("\u{187f7}", "\"\u{187f7}\""),
    ("\u{187f8}", "\"\\U000187f8\""),
    ("\u{11f00}", "\"\u{11f00}\""),
    ("\t\n\r", "\"\\t\\n\\r\""),
    ("'", "\"'\""),
];

#[test]
fn go_quote_matches_strconv_quote() {
    for (input, want) in QUOTES {
        assert_eq!(go_quote(input), *want, "input {input:?}");
    }
}

/// `%q` reaches the hex-decode error text with the caller's argument,
/// as dcrd's `rpcDecodeHexError` renders it.
#[test]
fn go_quote_renders_a_caller_argument_as_percent_q() {
    assert_eq!(go_quote("\u{7}"), r#""\a""#);
    assert_eq!(go_quote("ab\u{a0}"), r#""ab\u00a0""#);
    assert_eq!(go_quote("\u{7f}"), r#""\x7f""#);
}

