#[test]
fn strconv_parsers_match_go() {
    for (input, want) in PARSE_INTS {
        assert_eq!(go_parse_int(input).ok(), *want, "ParseInt {input:?}");
    }
    for (input, want) in PARSE_FLOATS {
        let got = go_parse_float(input).ok();
        match (got, want) {
            // Go's NaN has its own payload; only NaN-ness is portable.
            (Some(g), Some(w)) if f64::from_bits(*w).is_nan() => {
                assert!(g.is_nan(), "ParseFloat {input:?} = {g}")
            }
            _ => assert_eq!(got.map(f64::to_bits), *want, "ParseFloat {input:?}"),
        }
    }
}

/// `json.Unmarshal` of `{"ha\u017fh":"x","\u212aEY":5,"\u017fTATU\u017f":7}`
/// into a struct tagged `hash`, `key` and `status` fills all three:
/// `foldName` folds U+017F to `S` and U+212A to `K`.
#[test]
fn struct_keys_fold_like_go_fold_name() {
    let typ = GoType::strukt(
        "main",
        "T",
        vec![
            StructField::new("Hash", GoType::String).with_json_tag("hash"),
            StructField::new("Key", GoType::Int).with_json_tag("key"),
            StructField::new("Status", GoType::Int).with_json_tag("status"),
        ],
    );
    let got = gojson::decode(
        &typ,
        "{\"ha\u{17f}h\":\"x\",\"\u{212a}EY\":5,\"\u{17f}TATU\u{17f}\":7}",
    )
    .expect("decodes");
    assert_eq!(
        got,
        GoValue::Struct(vec![
            GoValue::String("x".to_string()),
            GoValue::Int(5),
            GoValue::Int(7),
        ])
    );
    assert!(go_fold_eq("\u{212a}ey", "key"));
    assert!(!go_fold_eq("\u{212b}ey", "key"));
}
